FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":1560520,"title":"Batman: Knightfall Part 1: Knightfall","description":"Arkham Asylum has been destroyed, and all its inmates have been unleashed upon Gotham City. As Batman races to round up some of his greatest enemies, he is pushed to his physical and mental limits and into a final confrontation with a new threat: the man called Bane!","duration":"1:19:00","genre":["Animation","Action","Adventure","Drama"],"release_date":"2026-06-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/caBIySpwuFi2i7ynvHIlnxJLOdN.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/360qdtu2hLnqMu8SVHMywn420w1.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//caBIySpwuFi2i7ynvHIlnxJLOdN.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//360qdtu2hLnqMu8SVHMywn420w1.jpg"},{"tmdb_id":980431,"title":"Avatar Aang: The Last Airbender","description":"Avatar Aang, the world''s last Airbender, learns of an ancient power that could save his culture from extinction. With the help of his friends, he embarks on a global quest to find it before it falls into the wrong hands and threatens to upend the peace they sacrificed everything to achieve.","duration":"1:39:00","genre":["Animation","Adventure","Fantasy","Action"],"release_date":"2026-07-24","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ezbrL1dMymKQZw7mDEWa2ZTzN7d.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/3sgnSfNT27Bx5O5ukr7B26mhEQq.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ezbrL1dMymKQZw7mDEWa2ZTzN7d.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//3sgnSfNT27Bx5O5ukr7B26mhEQq.jpg"},{"tmdb_id":1007757,"title":"Swapped","description":"A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.","duration":"1:42:00","genre":["Adventure","Animation","Family","Fantasy"],"release_date":"2026-05-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/zMwhWailP1WY7sb6AoE6b8ugoy.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//zMwhWailP1WY7sb6AoE6b8ugoy.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg"},{"tmdb_id":1632181,"title":"Accidental Partners","description":"Two women discover they were both scammed by the same man (who also got them pregnant). They form an alliance to take revenge.","duration":"1:50:00","genre":["Comedy","Romance"],"release_date":"2026-03-12","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/iCML6fBe3X0y06P33bM7dyYXPKZ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/j0CIVzeR7hRAPBPGR54qDZoOQpp.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//iCML6fBe3X0y06P33bM7dyYXPKZ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//j0CIVzeR7hRAPBPGR54qDZoOQpp.jpg"},{"tmdb_id":1311031,"title":"Demon Slayer: Kimetsu no Yaiba Infinity Castle","description":"The Demon Slayer Corps are drawn into the Infinity Castle, where Tanjiro, Nezuko, and the Hashira face terrifying Upper Rank demons in a desperate fight as the final battle against Muzan Kibutsuji begins.","duration":"2:36:00","genre":["Animation","Action","Fantasy"],"release_date":"2025-07-18","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/1RgPyOhN4DRs225BGTlHJqCudII.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fWVSwgjpT2D78VUh6X8UBd2rorW.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//1RgPyOhN4DRs225BGTlHJqCudII.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//fWVSwgjpT2D78VUh6X8UBd2rorW.jpg"},{"tmdb_id":1621552,"title":"Facing El Chapo","description":"Two Mexican officers must survive the final hours of their shift after crossing a ruthless cartel boss.","duration":"1:31:00","genre":["Crime","Action","Thriller"],"release_date":"2026-08-21","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/c4U96GrPRfnNrS01mBtqnocvlLJ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/alpf5v4UqSFawPmG9RX03Or4BDk.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//c4U96GrPRfnNrS01mBtqnocvlLJ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//alpf5v4UqSFawPmG9RX03Or4BDk.jpg"},{"tmdb_id":1333100,"title":"Attack on Titan: THE LAST ATTACK","description":"A colossal-sized omnibus film bringing together the last two episodes of Attack on Titan in the franchise''s first-ever theatrical experience. After venturing beyond the walls and separated from his comrades, Eren finds himself inspired by this new truth and plots the \"Rumbling,\" a terrifying plan to eradicate every living thing in the world. With the fate of the world hanging in the balance, a motley crew of Eren''s former comrades and enemies scramble to halt his deadly mission. The only question is, can they stop him?","duration":"2:25:00","genre":["Animation","Action","Adventure","Drama"],"release_date":"2024-03-20","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yPJyXYfDrlD7bEjAtTAQ8nqmRIf.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/wgwldDDlTDDMrluOMkpSA8lyKjv.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//yPJyXYfDrlD7bEjAtTAQ8nqmRIf.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//wgwldDDlTDDMrluOMkpSA8lyKjv.jpg"},{"tmdb_id":278,"title":"The Shawshank Redemption","description":"Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.","duration":"2:22:00","genre":["Drama","Crime"],"release_date":"1994-09-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/pNjh59JSxChQktamG3LMp9ZoQzp.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//pNjh59JSxChQktamG3LMp9ZoQzp.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg"},{"tmdb_id":122019,"title":"Macario","description":"Poor, hungry peasant Macario longs for just one good meal on the Day of the Dead. After his wife cooks a turkey for him, he meets three apparitions, the Devil, God, and Death. Each asks him to share his turkey, but he refuses all except Death. In return, Death gives him a bottle of water which will heal any illness. Soon, Macario is more wealthy than the village doctor, which draws the attention of the feared Inquisition.","duration":"1:31:00","genre":["Drama","Fantasy"],"release_date":"1960-06-09","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6SKhqqAPrJyPz9Cx1N1jaOBqV0a.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fKRzGm3BiuOv3MuolazFOEgB8EX.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//6SKhqqAPrJyPz9Cx1N1jaOBqV0a.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//fKRzGm3BiuOv3MuolazFOEgB8EX.jpg"},{"tmdb_id":238,"title":"The Godfather","description":"Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.","duration":"2:55:00","genre":["Drama","Crime"],"release_date":"1972-03-14","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ejdD20cdHNFAYAN2DlqPToXKyzx.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/3bhkrj58Vtu7enYs