INSERT INTO public.movie (
    "tmdb_id", "title", "description", "duration", "genre", "release_date", "backdrop_path", "poster_path", "small_backdrop_path", "small_poster_path"
)
SELECT
    m."tmdb_id", m."title", m."description", m."duration", m."genre", m."release_date", m."backdrop_path", m."poster_path", m."small_backdrop_path", m."small_poster_path"
FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":405,"title":"La Strada","description":"When Gelsomina, a naïve young woman, is purchased from her impoverished mother by brutish circus strongman Zampanò to be his wife and partner, she loyally endures her husband''s coldness and abuse as they travel the Italian countryside performing together. Soon Zampanò must deal with his jealousy and conflicted feelings about Gelsomina when she finds a kindred spirit in Il Matto, the carefree circus fool, and contemplates leaving Zampanò.","duration":"1:55:00","genre":["Drama"],"release_date":"1954-09-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/p6qM3hlviWYIgpPq4zNwrttn6Io.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/rwjbT0zlsUDMztaCcWjlWuxaEL1.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//p6qM3hlviWYIgpPq4zNwrttn6Io.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//rwjbT0zlsUDMztaCcWjlWuxaEL1.jpg"},{"tmdb_id":615453,"title":"Ne Zha","description":"A young boy is born as the reincarnation of a demonic power, into a society that hates and fears him. Destined by prophecy to bring destruction to the world, Nezha must choose between good and evil to see if he can change his fate.","duration":"1:50:00","genre":["Animation","Fantasy","Adventure"],"release_date":"2019-07-26","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/k1pJslKr4aDayw9kWwWnlC3MIP3.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/phM9bb6s9c60LA8qwsdk7U1N2cS.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//k1pJslKr4aDayw9kWwWnlC3MIP3.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//phM9bb6s9c60LA8qwsdk7U1N2cS.jpg"},{"tmdb_id":433694,"title":"Sgt. Stubby: An American Hero","description":"The true story of the most decorated dog in American military history - Sgt. Stubby - and the enduring bonds he forged with his brothers-in-arms in the trenches of World War I.","duration":"1:25:00","genre":["Animation","Adventure","Family","History","War"],"release_date":"2018-04-13","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/4pEbf7P2xlifhNmwAemcdAbomyZ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/rmpykGuvJznJw4iY4hpVVn5ZDdh.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//4pEbf7P2xlifhNmwAemcdAbomyZ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//rmpykGuvJznJw4iY4hpVVn5ZDdh.jpg"},{"tmdb_id":118340,"title":"Guardians of the Galaxy","description":"Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.","duration":"2:01:00","genre":["Action","Science Fiction","Adventure"],"release_date":"2014-07-30","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/uLtVbjvS1O7gXL8lUOwsFOH4man.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//uLtVbjvS1O7gXL8lUOwsFOH4man.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg"},{"tmdb_id":29264,"title":"The Exterminating Angel","description":"After a lavish dinner party, the guests find themselves unable to depart... and, over the next few days, all of their elaborate societal pretenses and façades deteriorate as they are reduced to living like animals.","duration":"1:33:00","genre":["Comedy","Drama","Fantasy"],"release_date":"1962-05-16","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/wJ4HyVZsbZRWH7BS3bLZsvO31rZ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/qqZXHvBFxUpo8Pfbyvgh4SYMiWm.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//wJ4HyVZsbZRWH7BS3bLZsvO31rZ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//qqZXHvBFxUpo8Pfbyvgh4SYMiWm.jpg"},{"tmdb_id":829,"title":"Chinatown","description":"Private eye Jake Gittes lives off of the murky moral climate of sunbaked, pre-World War II Southern California. Hired by a beautiful socialite to investigate her husband''s extra-marital affair, Gittes is swept into a maelstrom of double dealings and deadly deceits, uncovering a web of personal and political scandals that come crashing together.","duration":"2:10:00","genre":["Crime","Mystery","Thriller"],"release_date":"1974-06-20","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/pyvkujOZ5qvY2NlQVC71flfgVWE.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/kZRSP3FmOcq0xnBulqpUQngJUXY.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//pyvkujOZ5qvY2NlQVC71flfgVWE.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//kZRSP3FmOcq0xnBulqpUQngJUXY.jpg"},{"tmdb_id":150540,"title":"Inside Out","description":"When 11-year-old Riley moves to a new city, her Emotions team up to help her through the transition. Joy, Fear, Anger, Disgust and Sadness work together, but when Joy and Sadness get lost, they must journey through unfamiliar places to get back home.","duration":"1:35:00","genre":["Animation","Family","Adventure","Drama","Comedy"],"release_date":"2015-06-17","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/jJKZaTBNenlFclQyjrnvzkRmvWE.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//jJKZaTBNenlFclQyjrnvzkRmvWE.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg"},{"tmdb_id":1162,"title":"The Miracle Worker","description":"The true story of the frightening, lonely world of silence and darkness of 7-year-old Helen Keller who, since infancy, has never seen the sky, heard her mother''s voice or expressed her innermost feelings. Then Annie Sullivan, a 20-year-old teacher from Boston, arrives. Having just recently regained her own sight, the no-nonsense Annie reaches out to Helen through the power of touch, the only tool they have in common, and leads her bold pupil on a miraculous journey from fear and isolation to happiness and light.","duration":"1:46:00","genre":["Drama","History"],"release_date":"1962-05-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/5bvQEihHBKJ0Rs1J46HcG0wASDr.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/3dI6UVM5W1sz3MU9gNK5nVDcAyQ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//5bvQEihHBKJ0Rs1J46HcG0wASDr.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//3dI6UVM5W1sz3MU9gNK5nVDcAyQ.jpg"},{"tmdb_id":60243,"title":"A Separation","description":"A married couple are faced with a difficult decision – to improve the life of their child by moving to another country or to stay in Iran and look after a deteriorating parent who has Alzheimer''s disease.","duration":"2:03:00","genre":["Drama"],"release_date":"2011-02-15","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/vSQ2FK4LzevXeHeXvEHb7t4I0SW.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/xQadpnoLokxzN3hRpCPbBGpxsiz.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//vSQ2FK4LzevXeHeXvEHb7t4I0SW.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//xQadpnoLokxzN3hRpCPbBGpxsiz.jpg"},{"tmdb_id":53961,"title":"Brainstorm","description":"Neto is a middle class teenager living a normal life. After his father finds a marijuana cigarette on his pocket, he is sent to a mental institution, where he gets to know a completely absurd and inhumane reality in which people are devoured by a corrupt and cruel system.","duration":"1:24:00","genre":["Drama"],"release_date":"2001-06-22","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/nwPHdJp7bwFCFwcxUTuqHvtcESi.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/x6NXI2jvi9iKbzjjHRMtZ7mCPjB.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//nwPHdJp7bwFCFwcxUTuqHvtcESi.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//x6NXI2jvi9iKbzjjHRMtZ7mCPjB.jpg"},{"tmdb_id":28422,"title":"Love Exposure","description":"The story of a teenage boy called Yu, who falls for Yoko, a girl he runs into while operating for the sake of sin as an upskirt photographer in an offshoot of the porn industry. His attempts to woo her are complicated by a spot of cross-dressing - which convinces Yoko that she is lesbian - dalliances with kung-fu and crime, and a constant struggle with the guilt that''s a legacy of his Catholic upbringing.","duration":"3:57:00","genre":["Comedy","Drama","Romance"],"release_date":"2008-11-29","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ywVxppdRe8KN53P937p94mcXEoJ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/iCjpPMQRh1jcMQl7CZ5P2fR8aXN.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ywVxppdRe8KN53P937p94mcXEoJ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//iCjpPMQRh1jcMQl7CZ5P2fR8aXN.jpg"},{"tmdb_id":11010,"title":"The Postman","description":"Simple Italian postman learns to love poetry while delivering mail to a famous poet; he uses this to woo local beauty Beatrice.","duration":"1:54:00","genre":["Comedy","Drama","Romance"],"release_date":"1994-09-22","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/32pvxFiXNo2TdNpBiuHN8k2Mr4K.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/cUaCpjVDefYShKyLmkcDsiPaBHn.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//32pvxFiXNo2TdNpBiuHN8k2Mr4K.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//cUaCpjVDefYShKyLmkcDsiPaBHn.jpg"},{"tmdb_id":671,"title":"Harry Potter and the Philosopher''s Stone","description":"Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.","duration":"2:32:00","genre":["Adventure","Fantasy"],"release_date":"2001-11-16","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/hziiv14OpD73u9gAak4XDDfBKa2.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//hziiv14OpD73u9gAak4XDDfBKa2.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//wuMc08IPKEatf9rnMNXvIDxqP4W.jpg"},{"tmdb_id":152532,"title":"Dallas Buyers Club","description":"Loosely based on the true-life tale of Ron Woodroof, a drug-taking, women-loving, homophobic man who in 1986 was diagnosed with HIV/AIDS and given thirty days to live.","duration":"1:57:00","genre":["Drama","History"],"release_date":"2013-11-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/sbVKj98cq0FztCukzu47bu0H8o7.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7Fdh7gUq3plvQqxRbNYhWvDABXA.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//sbVKj98cq0FztCukzu47bu0H8o7.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//7Fdh7gUq3plvQqxRbNYhWvDABXA.jpg"},{"tmdb_id":116322,"title":"The Legend of La Llorona","description":"Based on a famous Mexican legend, a group of kids must stop the ghost of a woman whose guilt over the drowning of her own children leads her to abduct youngsters who wander the woods at night.","duration":"1:15:00","genre":["Animation","Family","Fantasy","Horror"],"release_date":"2011-10-21","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/uMyPeZ5WjouTHVEckilshhHULAg.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/vBiqoYfDIWKKzZTiQScqgCO09UD.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//uMyPeZ5WjouTHVEckilshhHULAg.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//vBiqoYfDIWKKzZTiQScqgCO09UD.jpg"},{"tmdb_id":94047,"title":"My Way","description":"During the invasion of Normandy the photograph of a slim Korean man in German uniform was found. It transpired that the man had served as a soldier in the Japanese, Russian and German armies. His incredible story inspired director Kang Je-Gyu to create this epic war drama.","duration":"2:17:00","genre":["Drama","Action","History","War"],"release_date":"2011-12-21","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/4QHF7kAYjIpZ5U8A0amvhRkHlZ1.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/3moPqIC1EBFilLI3YJNa5Nfel3e.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//4QHF7kAYjIpZ5U8A0amvhRkHlZ1.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//3moPqIC1EBFilLI3YJNa5Nfel3e.jpg"},{"tmdb_id":33602,"title":"Temple Grandin","description":"A biopic of Temple Grandin, an autistic American who has become one of the leading scientists in humane livestock handling.","duration":"1:48:00","genre":["Drama","History"],"release_date":"2010-02-06","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/aCURY1tNUkvrNnjw5qYJXTUp7z.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/gQhQ6yEkUkDDo1zugpq46PJN8xZ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//aCURY1tNUkvrNnjw5qYJXTUp7z.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//gQhQ6yEkUkDDo1zugpq46PJN8xZ.jpg"},{"tmdb_id":10674,"title":"Mulan","description":"When Imperial China calls one man from every family to defend the empire from invading Huns, a young woman disguises herself as a soldier to take her ailing father’s place. Facing ruthless invaders, brutal training, and the risk of execution if discovered, she must decide who she truly is— and what she’s willing to fight for.","duration":"1:28:00","genre":["Animation","Family","Adventure"],"release_date":"1998-06-18","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/mUYV0ZdsDEliGaQahcQH1F3grsP.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/jAbexAtB0aSfP5Ay4TpWHARyVnG.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//mUYV0ZdsDEliGaQahcQH1F3grsP.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//jAbexAtB0aSfP5Ay4TpWHARyVnG.jpg"},{"tmdb_id":770,"title":"Gone with the Wind","description":"The spoiled daughter of a Georgia plantation owner conducts a tumultuous romance with a cynical profiteer during the American Civil War and Reconstruction Era.","duration":"3:58:00","genre":["Drama","War","Romance"],"release_date":"1939-12-15","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/4FHcxMtVruMr7ltU2cItWssLjTP.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lNz2Ow0wGCAvzckW7EOjE03KcYv.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//4FHcxMtVruMr7ltU2cItWssLjTP.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//lNz2Ow0wGCAvzckW7EOjE03KcYv.jpg"},{"tmdb_id":18438,"title":"Castaway on the Moon","description":"Mr. Kim is jobless, lost in debt and has been dumped by his girlfriend. He decides to end it all by jumping into the Han River – only to find himself washed up on a small, mid-river island. He soon abandons thoughts of suicide or rescue and begins a new life as a castaway. His antics catch the attention of a young woman whose apartment overlooks the river. Her discovery changes both their lives.","duration":"1:59:00","genre":["Drama","Comedy","Romance"],"release_date":"2009-05-14","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/t9T6jKk2TqDqzpWTCMSeMNjYcX7.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/gGzovvmOEyNVUu4WEHtw9wfDsqI.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//t9T6jKk2TqDqzpWTCMSeMNjYcX7.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//gGzovvmOEyNVUu4WEHtw9wfDsqI.jpg"},{"tmdb_id":597,"title":"Titanic","description":"101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.","duration":"3:14:00","genre":["Drama","Romance"],"release_date":"1997-12-18","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/xXCuto8YVp5RFqBJ7yKmVmLOWpF.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//xXCuto8YVp5RFqBJ7yKmVmLOWpF.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg"},{"tmdb_id":122906,"title":"About Time","description":"The night after another unsatisfactory New Year''s party, Tim''s father reveals to him that the men in their family have the ability to travel through time. They can''t change history, but they can change what happens and has happened in their own lives. Thus begins the start of a lesson in learning to appreciate life itself as it is, as it comes, and most importantly, the people living alongside us.","duration":"2:03:00","genre":["Drama","Romance","Fantasy"],"release_date":"2013-06-27","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/einbto9qLXFx9QXxEHylaxDbKPx.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ls6zswrOZVhCXQBh96DlbnLBajM.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//einbto9qLXFx9QXxEHylaxDbKPx.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//ls6zswrOZVhCXQBh96DlbnLBajM.jpg"},{"tmdb_id":752,"title":"V for Vendetta","description":"In a world in which Great Britain has become a fascist state, a masked vigilante known only as “V” conducts guerrilla warfare against the oppressive British government. When V rescues a young woman from the secret police, he finds in her an ally with whom he can continue his fight to free the people of Britain.","duration":"2:12:00","genre":["Action","Thriller","Science Fiction"],"release_date":"2006-02-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/sFEYsEfzTx7hhjetlNr