    m."tmdb_id", m."title", m."description", m."duration", m."genre", m."release_date", m."backdrop_path", m."poster_path", m."small_backdrop_path", m."small_poster_path"
FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":15421,"title":"Becket","description":"Thomas Becket, Henry II''s longtime advisor, finds his friendship with the debauched king corroding when he is unwillingly appointed as Archbishop of Canterbury in an attempt to gain absolute loyalty from the Church.","duration":"2:28:00","genre":["Drama","History"],"release_date":"1964-03-11","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/bYwrsPgIloJsqD6nWfLycAp7tn6.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/swWmxVbq0pXv4wwsc2O803PiXR7.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//bYwrsPgIloJsqD6nWfLycAp7tn6.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//swWmxVbq0pXv4wwsc2O803PiXR7.jpg"},{"tmdb_id":14903,"title":"Pooh''s Grand Adventure: The Search for Christopher Robin","description":"Pooh gets confused when Christopher Robin leaves him a note to say that he has gone back to school after the holidays. So Pooh, Piglet, Tigger, Eeyore and Rabbit go in search of Christopher Robin which leads to a big adventure.","duration":"1:16:00","genre":["Animation","Family","Adventure"],"release_date":"1997-08-05","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/2Wc2Mo59HCvo7NkIHaax8nekpaQ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/tjk2Ig3I5bQvPUEH3A83aZebXEy.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//2Wc2Mo59HCvo7NkIHaax8nekpaQ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//tjk2Ig3I5bQvPUEH3A83aZebXEy.jpg"},{"tmdb_id":11773,"title":"Village of the Damned","description":"In a small English village everyone suddenly falls unconscious. When they awake every woman of child bearing age is pregnant. The resulting children have the same strange blond hair, eyes and a strong connection to each other.","duration":"1:17:00","genre":["Horror","Science Fiction"],"release_date":"1960-06-16","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/tlQ2OBQAC7woOTZgk1vE9U69vQT.jpg","poster_path":"https: