FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":1408208,"title":"Exit 8","description":"A man trapped in an endless sterile subway passageway sets out to find Exit 8. The rules of his quest are simple: do not overlook anything out of the ordinary. If you discover an anomaly, turn back immediately. If you don’t, carry on. Then leave from Exit 8. But even a single oversight will send him back to the beginning. Will he ever reach his goal and escape this infinite corridor?","duration":"1:35:00","genre":["Mystery","Thriller","Horror"],"release_date":"2025-08-03","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/3cVrg7tzSf5AgEecYWDOSAzXAeX.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/nQXYTvm6AY4WmtcPskroqC7Skh.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//3cVrg7tzSf5AgEecYWDOSAzXAeX.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//nQXYTvm6AY4WmtcPskroqC7Skh.jpg"},{"tmdb_id":1083381,"title":"Backrooms","description":"A strange doorway appears in the basement of a furniture showroom.","duration":"1:51:00","genre":["Horror","Mystery","Science Fiction"],"release_date":"2026-05-27","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/dqmMWNWfLnExDRpMtIMqI97GQFR.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//dqmMWNWfLnExDRpMtIMqI97GQFR.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg"},{"tmdb_id":823147,"title":"To Leslie","description":"A West Texas single mother wins the lottery and squanders it just as fast, leaving behind a world of heartbreak. Years later, with her charm running out and nowhere to go, she fights to rebuild her life and find redemption.","duration":"1:59:00","genre":["Drama"],"release_date":"2022-10-07","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7SGsNmrdb6hLQujKpvuBUrkKmcv.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/bFTgfsw4cnNjIZ