INSERT INTO public.movie (
    "tmdb_id", "title", "description", "duration", "genre", "release_date", "backdrop_path", "poster_path", "small_backdrop_path", "small_poster_path"
)
SELECT
    m."tmdb_id", m."title", m."description", m."duration", m."genre", m."release_date", m."backdrop_path", m."poster_path", m."small_backdrop_path", m."small_poster_path"
FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":953,"title":"Madagascar","description":"Four animal friends get a taste of the wild life when they break out of captivity at the Central Park Zoo and wash ashore on the island of Madagascar.","duration":"1:26:00","genre":["Adventure","Animation","Comedy","Family"],"release_date":"2005-05-25","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/tPaurpIUskVji5vwV0dhy9pq4Vs.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//tPaurpIUskVji5vwV0dhy9pq4Vs.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//zMpJY5CJKUufG9OTw0In4eAFqPX.jpg"},{"tmdb_id":528949,"title":"The Photographer of Mauthausen","description":"Spanish photographer Francesc Boix, imprisoned in the Mauthausen-Gusen concentration camp, works in the SS Photographic Service. Between 1943 and 1945, he hides, with the help of other prisoners, thousands of negatives, with the purpose of showing the freed world the atrocities committed by the Nazis, exhaustively documented. He will be a key witness during the Nuremberg Trials.","duration":"1:51:00","genre":["Drama","History","Thriller"],"release_date":"2018-10-26","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ljZOlqLtMa6gnTHcYn9y9lP0bK3.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6b4L0uLVgFsDfqPx0sFZbCRwIKH.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ljZOlqLtMa6gnTHcYn9y9lP0bK3.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//6b4L0uLVgFsDfqPx0sFZbCRwIKH.jpg"},{"tmdb_id":18533,"title":"Bronson","description":"A young man who was sentenced to 7 years in prison for robbing a post office ends up spending 30 years in solitary confinement. During this time, his own personality is supplanted by his alter ego, Charles Bronson.","duration":"1:32:00","genre":["Drama","Action","Crime"],"release_date":"2009-03-13","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/uc8FwdCQi3eD7JIbyiZuzo5n6Jv.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6diyyGIbBNiANsdIaCGtyv4IofR.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//uc8FwdCQi3eD7JIbyiZuzo5n6Jv.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//6diyyGIbBNiANsdIaCGtyv4IofR.jpg"},{"tmdb_id":13675,"title":"Frosty the Snowman","description":"A discarded silk top-hat becomes the focus of a struggle between a washed-up stage magician and a group of schoolchildren, after it magically brings a snowman to life. Realizing that newly-living Frosty will melt in spring unless he takes refuge in a colder climate, the magic snowman and Karen, a young girl whom he befriends, stow away on a freight train headed for the North Pole. Little do they know that the magician is following them, and he wants his hat back!","duration":"0:25:00","genre":["Family","Animation","TV Movie"],"release_date":"1969-12-07","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/69HEmEIgFCo6Te8ShHcFB1ERPeF.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/gw7ie4W3iW8nefnZ4kuw8dgYNM2.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//69HEmEIgFCo6Te8ShHcFB1ERPeF.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//gw7ie4W3iW8nefnZ4kuw8dgYNM2.jpg"},{"tmdb_id":9871,"title":"Ginger Snaps","description":"The story of two outcast sisters, Ginger and Brigitte, in the mindless suburban town of Bailey Downs. On the night of Ginger''s first period, she is savagely attacked by a wild creature. Ginger''s wounds miraculously heal but something is not quite right. Now Brigitte must save her sister and save herself.","duration":"1:48:00","genre":["Horror","Fantasy"],"release_date":"2000-12-11","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7GAgYVK29A4NADWhPbqC9c44X7P.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ozohDiJd7Oi65NEf8B0ya7lR9Fr.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//7GAgYVK29A4NADWhPbq