FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":5257,"title":"The Dish","description":"A group of maverick scientists on a remote Australian sheep farm are the globe''s only hope for obtaining the epic images of man''s first steps on the moon.","duration":"1:41:00","genre":["Comedy","Drama","History"],"release_date":"2000-10-19","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/rY1FcmerUUU32VcDJ4ylZrTkH6.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/zG83o1wpU3p7QTd382K4HtctLq0.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//rY1FcmerUUU32VcDJ4ylZrTkH6.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//zG83o1wpU3p7QTd382K4HtctLq0.jpg"},{"tmdb_id":1013850,"title":"A Real Pain","description":"Mismatched cousins David and Benji reunite for a tour through Poland to honor their beloved grandmother. The adventure takes a turn when the pair''s old tensions resurface against the backdrop of their family history.","duration":"1:30:00","genre":["Comedy","Drama"],"release_date":"2024-11-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fViElUGfdoZjtnVxvSpJX8TwxY6.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yaTFjMNh8D78dDHrglivOTv5YOx.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//fViElUGfdoZjtnVxvSpJX8TwxY6.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//yaTFjMNh8D78dDHrglivOTv5YOx.jpg"},{"tmdb_id":788045,"title":"My Best Friend Anne Frank","description":"Based on the real-life friendship between Anne Frank and Hannah Goslar, from Nazi-occupied Amsterdam to their harrowing reunion in a concentration camp.","duration":"1:43:00","genre":["History","War","Drama"],"release_date":"2021-10-07","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/giutn8OjG6WPQ7eqlk9PoJQyCae.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6codIHEKVYwbQ9Ey6CNoqWA9yxD.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//giutn8OjG6WPQ7eqlk9PoJQyCae.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//6codIHEKVYwbQ9Ey6CNoqWA9yxD.jpg"},{"tmdb_id":537190,"title":"Rampant","description":"Ancient Korea, 17th century. While the paranoid King Lee Jo of Joseon, vassal of the Qing dynasty, feels surrounded by conspirators and rebels, a dark evil emerges from the bowels of a merchant ship and the exiled Prince Lee Cheung returns to the royal court, ignoring that he will have to lead the few capable of defeating the ambitious humans and the bloody monsters who threaten to destroy the kingdom.","duration":"2:02:00","genre":["Action","Horror","Drama","Fantasy"],"release_date":"2018-10-25","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ylXU65OCcyXU3tZ00CCeTfwGFja.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/88F0FLFknAIdnPfXxWuSqnICD4W.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ylXU65OCcyXU3tZ00CCeTfwGFja.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//88F0FLFknAIdnPfXxWuSqnICD4W.jpg"},{"tmdb_id":316152,"title":"Free State of Jones","description":"In 1863, Mississippi farmer Newt Knight serves as a medic for the Confederate Army. Opposed to slavery, Knight would rather help the wounded than fight the Union. After his nephew dies in battle, Newt returns home to Jones County to safeguard his family but is soon branded an outlaw deserter. Forced to flee, he finds refuge with a group of runaway slaves hiding out in the swamps. Forging an alliance with the slaves and other farmers, Knight leads a rebellion that would forever change history.","duration":"2:20:00","genre":["Action","Drama","History","War"],"release_date":"2016-06-24","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/crVDxx9KgNW7Bm1wyXqBYpzG2TS.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fTB6p9QwPRKIuK5LtB5CZXlkx5b.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//crVDxx9KgNW7Bm1wyXqBYpzG2TS.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//fTB6p9QwPRKIuK5LtB5CZXlkx5b.jpg"},{"t