INSERT INTO public.movie (
    "tmdb_id", "title", "description", "duration", "genre", "release_date", "backdrop_path", "poster_path", "small_backdrop_path", "small_poster_path"
)
SELECT
    m."tmdb_id", m."title", m."description", m."duration", m."genre", m."release_date", m."backdrop_path", m."poster_path", m."small_backdrop_path", m."small_poster_path"
FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":38368,"title":"Uncle Boonmee Who Can Recall His Past Lives","description":"Suffering from a kidney disease and sure of his death, Uncle Boonmee assembles his relatives in the countryside. He reminisces about his past lives and plans to visit a place before dying.","duration":"1:54:00","genre":["Drama","Fantasy"],"release_date":"2010-06-25","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/sraqqxwStjlhe82vb0mGx3VuHsD.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/kPFkC9EBvllCIuDTR7A0DSEK6gJ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//sraqqxwStjlhe82vb0mGx3VuHsD.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//kPFkC9EBvllCIuDTR7A0DSEK6gJ.jpg"},{"tmdb_id":27936,"title":"Micmacs","description":"While standing in the doorway of the video shop where he works, Bazil is inadvertently shot in the head. Now homeless and jobless, he is taken in by a troupe of misfits who live in a giant mound of trash. There Bazil begins his quest for revenge against the people who produced the gun that shot him.","duration":"1:44:00","genre":["Action","Comedy","Crime"],"release_date":"2009-10-28","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/awhWLCEmA4Suxf3po9xXAGDwzZY.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yiqooJWNDEVsp8lbdTrTBvLAk0m.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//awhWLCEmA4Suxf3po9xXAGDwzZY.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//yiqooJWNDEVsp8lbdTrTBvLAk0m.jpg"},{"tmdb_id":8349,"title":"The Red Baron","description":"Richthofen goes off to war like thousands of other men. As fighter pilots, they become cult heroes for the soldiers on the battlefields. Marked by sportsmanlike conduct, technical exactitude and knightly propriety, they have their own code of honour. Before long he begins to understand that his hero status is deceptive. His love for Kate, a nurse, opens his eyes to the brutality of war.","duration":"1:46:00","genre":["Action","Adventure","Drama","History","War"],"release_date":"2008-03-29","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/A20D83vGtFGF47rYF4TjHEw06Dm.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lUuryram6Aoa11dCgoXohR8avjU.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//A20D83vGtFGF47rYF4TjHEw06Dm.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//lUuryram6Aoa11dCgoXohR8avjU.jpg"},{"tmdb_id":5001,"title":"Before Night Falls","description":"Spanning several decades, this powerful biopic offers a glimpse into the life of famed Cuban poet and novelist Reinaldo Arenas, an artist who was vilified for his homosexuality in Fidel Castro''s Cuba.","duration":"2:14:00","genre":["Drama"],"release_date":"2000-09-03","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/jnJ4i6vPQETcfjxOvAODxzsdQfX.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/kb2dqj73cfmt6qHAh1ySIlVm6v0.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//jnJ4i6vPQETcfjxOvAODxzsdQfX.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//kb2dqj73cfmt6qHAh1ySIlVm6v0.jpg"},{"tmdb_id":330764,"title":"The Brand New Testament","description":"God lives in Brussels. On Earth though, God is a coward, morally pathetic and odious to his family. His daughter, Ea, is bored at home and can''t stand being locked up in a small apartment in ordinary Brussels, until the day she decides to revolt against her dad...","duration":"1:54:00","genre":["Comedy","Fantasy"],"release_date":"2015-09-02","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/v3LsiN0K6RQTdxDiJY9DMk9dilW.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/eRKgcuXSP9KiGlh2tlS85oh6ceN.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//v3LsiN0K6RQTdxDiJY9DMk9dilW.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//eRKgcuXSP9KiGlh2tlS85oh6ceN.jpg"},{"tmdb_id":80321,"title":"Madagascar 3: Europe''s Most Wanted","description":"Animal pals Alex, Marty, Melman, and Gloria are still trying to make it back to New York''s Central Park Zoo. They are forced to take a detour to Europe to find the penguins and chimps who broke the bank at a Monte Carlo casino. When French animal-control officer Capitaine Chantel DuBois picks up their scent, Alex and company are forced to hide out in a traveling circus.","duration":"1:33:00","genre":["Animation","Family","Comedy","Adventure"],"release_date":"2012-06-06","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/uDR9UjSuykTL8g3N3bh3siZ4n3C.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ekraj4ksvIKeuvQVEevEJkuybZd.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//uDR9UjSuykTL8g3N3bh3siZ4n3C.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//ekraj4ksvIKeuvQVEevEJkuybZd.jpg"},{"tmdb_id":9523,"title":"Lantana","description":"Plagued with grief over the murder of her daughter, Valerie Somers suspects that her husband John is cheating on her. When Valerie disappears, Detective Leon Zat attempts to solve the mystery of her absence. A complex web of love, sex and deceit emerges -- drawing in four related couples whose various partners are distrustful and suspicious about each other''s involvement.","duration":"2:01:00","genre":["Crime","Drama","Mystery"],"release_date":"2001-10-04","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/s9ivjpkMFQNRNXbfGBGgFGcthCS.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/nTEUCdpDsfVDZJ5H0ndP1EmVtj.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//s9ivjpkMFQNRNXbfGBGgFGcthCS.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//nTEUCdpDsfVDZJ5H0ndP1EmVtj.jpg"},{"tmdb_id":6415,"title":"Three Kings","description":"A group of American soldiers stationed in Iraq at the end of the Gulf War find a map they believe will take them to a huge cache of stolen Kuwaiti gold hidden near their base, and they embark on a secret mission that''s destined to change everything.","duration":"1:54:00","genre":["Action","Comedy","War"],"release_date":"1999-09-27","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/gysZn2XnFlDDQROXdBPiku4Aujg.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fClJQW8xn8wHOFqoA4jUn0PZh1f.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//gysZn2XnFlDDQROXdBPiku4Aujg.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//fClJQW8xn8wHOFqoA4jUn0PZh1f.jpg"},{"tmdb_id":1064028,"title":"Subservience","description":"With his wife out sick, a struggling father brings home a lifelike AI, only to have his self-aware new help want everything her new family has to offer... Like the affection of her owner and she''ll kill to get it.","duration":"1:45:00","genre":["Horror","Science Fiction","Thriller"],"release_date":"2024-08-15","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/co7oxvpWxgd6FZU24DnljDDHYQA.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/gBenxR01Uy0Ev9RTIw6dVBPoyQU.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//co7oxvpWxgd6FZU24DnljDDHYQA.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//gBenxR01Uy0Ev9RTIw6dVBPoyQU.jpg"},{"tmdb_id":823482,"title":"Dream Scenario","description":"Hapless family man Paul Matthews finds his life turned upside down when millions of strangers suddenly start seeing him in their dreams. But when his nighttime appearances take a nightmarish turn, Paul is forced to navigate his newfound stardom.","duration":"1:42:00","genre":["Comedy","Fantasy"],"release_date":"2023-11-10","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/2WRe1y5S1jGWTKUcSPPmD1Ixq56.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/eMaAi8wTI5wON8pp33w3BDuGyZ8.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//2WRe1y5S1jGWTKUcSPPmD1Ixq56.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//eMaAi8wTI5wON8pp33w3BDuGyZ8.jpg"},{"tmdb_id":532953,"title":"Purl","description":"Purl, an earnest ball of yarn, gets a job at a fast-paced, male-centered startup company. Things start to unravel as Purl tries to fit in with this tight-knit group, but she must ask herself how far is she willing to go to get the acceptance she yearns for and if, in the end, it is worth it.","duration":"0:09:00","genre":["Animation","Comedy"],"release_date":"2019-01-18","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/z0imgSRUugAdS7FKiEGw3t8Jj4v.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/A8to7TlVMBwMuDgi2DJ9rVJsobE.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//z0imgSRUugAdS7FKiEGw3t8Jj4v.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//A8to7TlVMBwMuDgi2DJ9rVJsobE.jpg"},{"tmdb_id":514710,"title":"Modest Heroes","description":"Two tiny, aquatic humanoids search for their missing father, a boy battles a lethal allergy to eggs, and an invisible salaryman tries to become a hero.","duration":"0:54:00","genre":["Animation","Fantasy","Adventure","Drama"],"release_date":"2018-08-24","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9ahTjsTLJAxbkCQ49J1zzsIzQrP.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/5jURYLaG6BX0klRHsiHc3pzOlOm.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//9ahTjsTLJAxbkCQ49J1zzsIzQrP.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//5jURYLaG6BX0klRHsiHc3pzOlOm.jpg"},{"tmdb_id":406994,"title":"Better Watch Out","description":"On a quiet suburban street tucked within a ''safe neighborhood'', a babysitter must defend a twelve-year-old boy from strangers breaking into the house, only to discover that this is far from a normal home invasion.","duration":"1:29:00","genre":["Horror","Thriller","Comedy"],"release_date":"2017-10-06","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/r7RdSJWKeqgQ6ZsxM08d2xRoKor.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/liI4c3GYaKuAo4FsCF4RKvFFqbV.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//r7RdSJWKeqgQ6ZsxM08d2xRoKor.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//liI4c3GYaKuAo4FsCF4RKvFFqbV.jpg"},{"tmdb_id":52744,"title":"Falling in Love","description":"During shopping for Christmas, Frank and Molly run into each other. This fleeting short moment will start to change their lives, when they recognize each other months later in the train home and have a good time together. Although both are married and Frank has two little kids, they meet more and more often, their friendship becoming the most precious thing in their lives.","duration":"1:46:00","genre":["Drama","Romance"],"release_date":"1984-11-21","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/kKoiL1jeLFqqH2StTKvFnT54exu.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/c8Ti4tOwAmY6RhUxV9JsXl2W4l7.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//kKoiL1jeLFqqH2StTKvFnT54exu.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//c8Ti4tOwAmY6RhUxV9JsXl2W4l7.jpg"},{"tmdb_id":21128,"title":"One False Move","description":"Following a series of drug deals and murders, three criminals -- Fantasia, Ray Malcolm and Pluto -- travel from Los Angeles to Houston, finally arriving in a small Arkansas town to go into hiding. Two detectives from the LAPD, who are already on the case, contact the town''s sheriff, Dale Dixon, to alert him of the fugitives'' presence in the area. Underestimating Dixon, the criminals have no idea what they are about to face.","duration":"1:45:00","genre":["Crime","Drama","Thriller"],"release_date":"1992-05-08","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/iwOolqARbddbajguEIxM2ClP3aw.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/x5xCkGw4jutMcc8nmWLKNzbDKht.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//iwOolqARbddbajguEIxM2ClP3aw.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//x5xCkGw4jutMcc8nmWLKNzbDKht.jpg"},{"tmdb_id":6639,"title":"Love in the Time of Cholera","description":"In Colombia just after the Great War, an old man falls from a ladder; dying, he professes great love for his wife. After the funeral, a man calls on the widow - she dismisses him angrily. Flash back more than 50 years to the day Florentino Ariza, a telegraph boy, falls in love with Fermina Daza, the daughter of a mule trader.","duration":"2:19:00","genre":["Drama","Romance"],"release_date":"2007-10-04","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/qD4oylPXPLxQCULTWPzhwWSeEVI.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lU3uvWGQlWeySxrUlJpxNaHW2Ra.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//qD4oylPXPLxQCULTWPzhwWSeEVI.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//lU3uvWGQlWeySxrUlJpxNaHW2Ra.jpg"},{"tmdb_id":616803,"title":"Breaking Surface","description":"Two Swedish/Norwegian half sisters go on a winter diving trip in Northern Norway, when they get trapped after a rockslide.","duration":"1:22:00","genre":["Drama","Thriller"],"release_date":"2020-02-14","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/mBijGSEEkIVt24ruvTxFuQWRKJm.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/zlOvKg5WkXcwcmqy2KaiXoXLAky.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//mBijGSEEkIVt24ruvTxFuQWRKJm.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//zlOvKg5WkXcwcmqy2KaiXoXLAky.jpg"},{"tmdb_id":464446,"title":"Return","description":"A young man returns home for the weekend to discover the difficulty of juggling friends, parents, magic mushrooms and several thousand chickens.","duration":"0:15:00","genre":["Comedy"],"release_date":"2015-07-04","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/h4SIEXZcj5tY9w8mEWendCZJ1kE.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/v4F270SLg2HM89XzHV4i7o1UXyt.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//h4SIEXZcj5tY9w8mEWendCZJ1kE.jpg","smal