FROM jsonb_populate_recordset(
    NULL::public.movie,
    '[{"tmdb_id":8266,"title":"Female Agents","description":"May 1944, a group of French servicewomen and resistance fighters are enlisted into the British Special Operations Executive commando group under the command of Louise Desfontaines and her brother Pierre. Their mission, to rescue a British army geologist caught reconnoitering the beaches at Normandy.","duration":"1:57:00","genre":["War","History"],"release_date":"2008-02-08","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/91EdS983zWz6gjwq3nPN1D8ZIHh.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/drOSLa0lNoitjRyku7wBgf6bNyu.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//91EdS983zWz6gjwq3nPN1D8ZIHh.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//drOSLa0lNoitjRyku7wBgf6bNyu.jpg"},{"tmdb_id":1413,"title":"M. Butterfly","description":"In 1960s China, French diplomat Rene Gallimard falls in love with opera singer Song Liling – but Song is not at all who Gallimard thinks.","duration":"1:41:00","genre":["Romance","Drama","History"],"release_date":"1993-10-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7cqxSTOUe0olgvjXxRs8XedFjOr.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/vfutnJ9sgpAtNuPemksd26gd5dC.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//7cqxSTOUe0olgvjXxRs8XedFjOr.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//vfutnJ9sgpAtNuPemksd26gd5dC.jpg"},{"tmdb_id":664,"title":"Twister","description":"An unprecedented series of violent tornadoes is sweeping across Oklahoma. Tornado chasers, headed by Dr. Jo Harding, attempt to release a groundbreaking device that will allow them to track them and create a more advanced warning system. They are joined by Jo''s soon to be ex-husband Bill, a former tornado chaser himself, and his girlfriend Melissa.","duration":"1:53:00","genre":["Action","Adventure","Drama"],"release_date":"1996-05-10","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/5oCAo7LFj2x0yByfi5JYirGnK8I.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/d4ie3f6QTvNw40V770Uzo87SDZn.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//5oCAo7LFj2x0yByfi5JYirGnK8I.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//d4ie3f6QTvNw40V770Uzo87SDZn.jpg"},{"tmdb_id":74,"title":"War of the Worlds","description":"Ray Ferrier is a divorced dockworker and less-than-perfect father. Soon after his ex-wife and her new husband drop off his teenage son and young daughter for a rare weekend visit, a strange and powerful lightning storm touches down.","duration":"1:57:00","genre":["Adventure","Thriller","Science Fiction"],"release_date":"2005-06-28","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/bInicBgSHfQiWLbnRT5jxw9Grvm.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6Biy7R9LfumYshur3YKhpj56MpB.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//bInicBgSHfQiWLbnRT5jxw9Grvm.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//6Biy7R9LfumYshur3YKhpj56MpB.jpg"},{"tmdb_id":802219,"title":"Bob Marley: One Love","description":"Jamaican singer-songwriter Bob Marley overcomes adversity to become the most famous reggae musician in the world.","duration":"1:44:00","genre":["Music","History","Drama"],"release_date":"2024-02-14","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lHPap2xBR7DgWLiu6RsfKESgzAi.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/1lQftpEARVVB9op4TaYiIbactzG.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//lHPap2xBR7DgWLiu6RsfKESgzAi.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//1lQftpEARVVB9op4TaYiIbactzG.jpg"},{"tmdb_id":43194,"title":"Ulysses","description":"A retelling of Homer''s The Odyssey, focusing on Ulysses''s ten-year journey home to Ithaca following the Trojan War, where he faces various mythical challenges while his wife Penelope fends off suitors.","duration":"1:40:00","genre":["Adventure","Fantasy"],"release_date":"1954-10-06","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/oHnoObrxhfHnHgYzQIyIhpJhI47.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/1HwrZ6SVRcUiPWSx3ecc7DFqey0.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//oHnoObrxhfHnHgYzQIyIhpJhI47.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//1HwrZ6SVRcUiPWSx3ecc7DFqey0.jpg"},{"tmdb_id":11977,"title":"Caddyshack","description":"At an exclusive country club, an ambitious young caddy, Danny Noonan, eagerly pursues a caddy scholarship in hopes of attending college and, in turn, avoiding a job at the lumber yard. In order to succeed, he must first win the favour of the elitist Judge Smails, and then the caddy golf tournament which Smails sponsors.","duration":"1:38:00","genre":["Comedy"],"release_date":"1980-07-25","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/3tqRm30c1Nbe82xvBOdRhYh0Uet.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lXnNz7zOXCsftMDVoU3VSo0Eioi.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//3tqRm30c1Nbe82xvBOdRhYh0Uet.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//lXnNz7zOXCsftMDVoU3VSo0Eioi.jpg"},{"tmdb_id":11064,"title":"Brewster''s Millions","description":"Monty Brewster, an aging minor-league baseball player, stands to inherit $300 million if he can successfully spend $30 million in 30 days without anything to show for it, and without telling anyone what he''s up to... A task that''s a lot harder than it sounds!","duration":"1:37:00","genre":["Comedy"],"release_date":"1985-05-22","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/hiL9QOIj5qT5FK61EGlM47vTAho.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/t4p8r8kfB2jHiK8J36XnfSP8cRO.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//hiL9QOIj5qT5FK61EGlM47vTAho.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//t4p8r8kfB2jHiK8J36XnfSP8cRO.jpg"},{"tmdb_id":9917,"title":"Wai